// crate: unicode-width-0.2.2/src/tables.rs:465 str_width
export function str_width(s: string): number {
  // PORT: `s.chars().rfold(..)`; walks the chars from the end.
  const chars = Array.from(s, (ch) => ch.codePointAt(0)!);
  let sum = 0;
  let next_info = WidthInfo.DEFAULT;
  for (let i = chars.length - 1; i >= 0; i--) {
    const [add, info] = width_in_str(chars[i]!, next_info);
    sum = sum + add;
    next_info = info;
  }
  return sum;
}

