/// Whether this character is a default-ignorable combining mark
/// or ZWJ. These characters won't interrupt non-Arabic ligatures.
// crate: unicode-width-0.2.2/src/tables.rs:826 is_ligature_transparent
export function is_ligature_transparent(c: number): boolean {
  return (
    c === 0x34f ||
    (c >= 0x17b4 && c <= 0x17b5) ||
    (c >= 0x180b && c <= 0x180d) ||
    c === 0x180f ||
    c === 0x200d ||
    (c >= 0xfe00 && c <= 0xfe0f) ||
    (c >= 0xe0100 && c <= 0xe01ef)
  );
}

